// Fix Supabase lessons whose sanity_slug points to a NON-EXISTENT Sanity doc,
// causing the app to render thin legacy content_blocks instead of the rich body.
// Each op retargets sanity_slug -> the correct existing academyModule _id.
//
// The op list is generated by the ecosystem audit (see PLAN_SANITY_ECOSYSTEM.md)
// and lives in scripts/relink_ops.json. Every "new" target is verified to exist
// in Sanity before any write. DRY RUN unless --commit.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { createClient } from "@supabase/supabase-js";

const __dir = dirname(fileURLToPath(import.meta.url));
const env = readFileSync(join(__dir, "../.env.local"), "utf8");
for (const line of env.split("\n")) {
  const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.+?)\s*$/);
  if (m) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
}
const db = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);
const COMMIT = process.argv.includes("--commit");

const ops = JSON.parse(readFileSync(join(__dir, "relink_ops.json"), "utf8"));

// Verify every target _id actually exists in Sanity (and has a body) before writing.
async function sanityIdsWithBody(ids) {
  const groq = `*[_type=="academyModule" && _id in $ids && defined(body) && count(body) > 0]._id`;
  const params = encodeURIComponent(JSON.stringify(ids));
  const url =
    "https://fxz10xl7.api.sanity.io/v2021-06-07/data/query/production?query=" +
    encodeURIComponent(groq) + "&$ids=" + params;
  const r = await (await fetch(url)).json();
  return new Set(r.result || []);
}

const targets = [...new Set(ops.map((o) => o.new))];
const valid = await sanityIdsWithBody(targets);

let ready = [], bad = [];
for (const o of ops) {
  if (valid.has(o.new)) ready.push(o);
  else bad.push(o);
}

console.log(`Relink ops: ${ops.length} | targets valid (exist + have body): ${ready.length}`);
for (const o of ready) console.log(`  ${o.lesson_slug.padEnd(44)} ${o.old}  ->  ${o.new}`);
if (bad.length) {
  console.log(`\n⚠️  ${bad.length} ops skipped — target missing or empty in Sanity:`);
  for (const o of bad) console.log(`  ${o.lesson_slug} -> ${o.new}`);
}

if (!COMMIT) {
  console.log("\nDRY RUN — re-run with --commit to update sanity_slug.");
  process.exit(0);
}

let ok = 0, fail = 0;
for (const o of ready) {
  const { error } = await db.from("lessons").update({ sanity_slug: o.new }).eq("id", o.lesson_id);
  if (error) { fail++; console.error("FAIL", o.lesson_slug, error.message); } else ok++;
}
console.log(`\n✅ Relinked ${ok} lessons${fail ? `, ${fail} failed` : ""}.`);
